<div class="wrap">

  <div class="hero">
    <h1>f(x) = e<sup>x</sup> − ax − 3 与 <span>两个零点</span> · 交互解题台</h1>
    <div class="problem">
      已知函数 <b>f(x) = e<sup>x</sup> − ax − 3（a ∈ R）</b>。<br>
      <span class="q">（1）当 x ≥ 0 时，若不等式 f(x) ≥ <sup>x²</sup>⁄₂ − 2 恒成立，求 a 的取值范围；</span><br>
      <span class="q">（2）若 f(x) 有两个零点 x<sub>1</sub>，x<sub>2</sub>，且 x<sub>1</sub> &lt; x<sub>2</sub>。</span><br>
      <span class="q">　　（i）求 a 的取值范围；　（ii）证明：3e<sup>x₁</sup> + e<sup>x₂</sup> &gt; 3a。</span>
    </div>
  </div>

  <div class="stage">
    <div class="boardcard">
      <svg id="board" viewBox="0 0 930 620" preserveAspectRatio="xMidYMid meet"></svg>
      <div class="ctrlbar">
        <label for="aSlider">参数 a</label>
        <input id="aSlider" type="range" min="-1.5" max="4" step="0.05" value="1.2">
        <output id="aOut">1.20</output>
      </div>
    </div>

    <div class="side">
      <div class="stepbar" id="stepbar"></div>
      <div class="card" id="card"></div>
    </div>
  </div>
</div>

<script>
(function(){
"use strict";

/* ==================== 基础 ==================== */
const SVGNS = "http://www.w3.org/2000/svg";
const board = document.getElementById("board");
const aSlider = document.getElementById("aSlider");
const aOut = document.getElementById("aOut");
const cardEl = document.getElementById("card");
const stepbarEl = document.getElementById("stepbar");

const BOX = { x0: 84, x1: 868, y0: 44, y1: 556 };

const state = { step: 0, a: 1.2 };

const STEPS = [
  { label:"① 认识函数",   a:{ min:-1.5, max:4,   step:0.05, def:1.2 } },
  { label:"② 转成面积",   a:{ min:0,    max:2.8, step:0.02, def:1.7 } },
  { label:"③ 解出 a",     a:{ min:0.6,  max:3.4, step:0.02, def:1.4 } },
  { label:"④ 两个零点",   a:{ min:-0.8, max:4,   step:0.05, def:1.5 } },
  { label:"⑤ 证明不等式", a:{ min:1.0,  max:4,   step:0.02, def:1.6 } },
  { label:"⑥ 结论",       a:{ min:1.0,  max:4,   step:0.02, def:1.6 } }
];

/* ==================== 工具 ==================== */
function mk(tag, attrs, txt){
  const e = document.createElementNS(SVGNS, tag);
  if(attrs) for(const k in attrs) e.setAttribute(k, attrs[k]);
  if(txt !== undefined && txt !== null) e.textContent = txt;
  return e;
}
function fmt(v, d){
  d = (d === undefined) ? 2 : d;
  if(!isFinite(v)) return "—";
  if(Math.abs(v) < 1e-9) return "0";
  let s = v.toFixed(d);
  if(s.indexOf(".") >= 0) s = s.replace(/0+$/,"").replace(/\.$/,"");
  return s;
}
function mapper(xmin, xmax, ymin, ymax){
  const X = x => BOX.x0 + (x - xmin) / (xmax - xmin) * (BOX.x1 - BOX.x0);
  const Y = y => BOX.y1 - (y - ymin) / (ymax - ymin) * (BOX.y1 - BOX.y0);
  return { X, Y, xmin, xmax, ymin, ymax };
}
function curvePath(m, f, xa, xb, N){
  N = N || 360;
  let d = "", pen = false;
  for(let i = 0; i <= N; i++){
    const x = xa + (xb - xa) * i / N;
    let y;
    try { y = f(x); } catch(e){ pen = false; continue; }
    if(typeof y !== "number" || !isFinite(y)){ pen = false; continue; }
    const px = m.X(x), py = m.Y(y);
    if(py < BOX.y0 - 900 || py > BOX.y1 + 900){ pen = false; continue; }
    d += (pen ? "L" : "M") + px.toFixed(2) + " " + py.toFixed(2) + " ";
    pen = true;
  }
  return d;
}
function findRoots(f, xa, xb, N){
  N = N || 1600;
  const out = [];
  let prev = f(xa), prevx = xa;
  for(let i = 1; i <= N; i++){
    const x = xa + (xb - xa) * i / N;
    const cur = f(x);
    if(!isFinite(cur)){ prevx = x; prev = cur; continue; }
    if(prev === 0){ out.push(prevx); }
    else if(isFinite(prev) && prev * cur < 0){
      let lo = prevx, hi = x;
      for(let k = 0; k < 70; k++){
        const mid = (lo + hi) / 2;
        if(f(lo) * f(mid) <= 0) hi = mid; else lo = mid;
      }
      out.push((lo + hi) / 2);
    }
    prev = cur; prevx = x;
  }
  return out;
}

/* ==================== 坐标轴 ==================== */
function drawAxes(m, xt, yt){
  const g = mk("g");
  const yZero = m.Y(0), xZero = m.X(0);
  const showX = (m.ymin <= 0 && 0 <= m.ymax);
  const showY = (m.xmin <= 0 && 0 <= m.xmax);

  if(showX){
    g.appendChild(mk("line", {x1:BOX.x0, y1:yZero, x2:BOX.x1, y2:yZero,
      stroke:"#94a3b8", "stroke-width":1.4}));
    g.appendChild(mk("path", {d:"M"+BOX.x1+","+yZero+" l-11,-4.5 v9 z", fill:"#94a3b8"}));
    g.appendChild(mk("text", {x:BOX.x1-4, y:yZero-11, "text-anchor":"end",
      "font-size":14, fill:"#64748b", "font-style":"italic"}, "x"));
  }
  if(showY){
    g.appendChild(mk("line", {x1:xZero, y1:BOX.y1, x2:xZero, y2:BOX.y0,
      stroke:"#94a3b8", "stroke-width":1.4}));
    g.appendChild(mk("path", {d:"M"+xZero+","+BOX.y0+" l-4.5,11 h9 z", fill:"#94a3b8"}));
    g.appendChild(mk("text", {x:xZero+9, y:BOX.y0+15,
      "font-size":14, fill:"#64748b", "font-style":"italic"}, "y"));
  }

  (xt || []).forEach(v=>{
    const px = m.X(v);
    if(px < BOX.x0 - 2 || px > BOX.x1 + 2) return;
    g.appendChild(mk("line", {x1:px, y1:yZero-4, x2:px, y2:yZero+4,
      stroke:"#94a3b8", "stroke-width":1.2}));
    g.appendChild(mk("text", {x:px, y:yZero+18, "text-anchor":"middle",
      "font-size":12.5, fill:"#64748b"}, fmt(v)));
  });
  (yt || []).forEach(v=>{
    const py = m.Y(v);
    if(py < BOX.y0 - 2 || py > BOX.y1 + 2) return;
    g.appendChild(mk("line", {x1:xZero-4, y1:py, x2:xZero+4, y2:py,
      stroke:"#94a3b8", "stroke-width":1.2}));
    g.appendChild(mk("text", {x:xZero-8, y:py+4, "text-anchor":"end",
      "font-size":12.5, fill:"#64748b"}, fmt(v)));
  });
  return g;
}

/* 带上下标的小标题文字 */
function richLabel(x, y, pieces, attrs){
