    const xm = Math.log(a), ym = f(xm);
    if(ym > m.ymin && ym < m.ymax){
      board.appendChild(mk("line", {x1:m.X(xm), y1:m.Y(0), x2:m.X(xm), y2:m.Y(ym),
        stroke:"#d97706", "stroke-width":1.6, "stroke-dasharray":"6 4"}));
