  return { roots: roots, minVal: minVal, xmin: xmin };
}

/* ==================== 步骤 4：证明 ==================== */
function drawStep4(a, showAll){
  const m = mapper(-3.8, 4.3, -6, 34);
  board.appendChild(drawAxes(m, [-3,-2,-1,1,2,3,4], [10,20,30]));

  const E = x => Math.exp(x);
  const L = x => a*x + 3;

  board.appendChild(mk("path", {d: curvePath(m, E, -3.8, 3.62, 400), fill:"none",
