  board.appendChild(mk("path", {d: curvePath(m, L, -3.8, 4.3, 2), fill:"none",
    stroke:"#d97706", "stroke-width":3}));

  const f = x => Math.exp(x) - a*x - 3;
  const roots = findRoots(f, -12, 10);
  let x1 = roots.length >= 2 ? roots[0] : null;
  let x2 = roots.length >= 2 ? roots[1] : null;

  /* P1 */
  if(x1 !== null && x1 > m.xmin && x1 < m.xmax){
    board.appendChild(mk("circle", {cx:m.X(x1), cy:m.Y(E(x1)), r:6.5, fill:"#dc2626",
